//! Exact, product-specific anchors for approved existing-profile setup.

use std::time::Duration;

use super::types::BrowserProduct;

/// Cold browser profiles can spend several seconds initializing their internal
/// DevTools page. Keep one bounded timeout across platform adapters so a slow
/// first render does not become platform-specific behavior.
pub const EXISTING_PROFILE_SETUP_READY_TIMEOUT: Duration = Duration::from_secs(12);

/// Accessibility-visible anchors for a Chromium product's internal remote
/// debugging page. Adapters still require an exact native window and exact
/// control matches; these values only describe the product surface.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct BrowserSetupDescriptor {
    pub product: BrowserProduct,
    pub product_name: &'static str,
    pub setup_url: &'static str,
    pub page_titles: &'static [&'static str],
    pub page_heading: &'static str,
    pub checkbox_label: &'static str,
    pub tab_close_labels: &'static [&'static str],
}

const CHROME_TITLES: &[&str] = &["Inspect with Chrome Developer Tools"];
const CHROMIUM_TITLES: &[&str] = &[
    "Inspect with Chromium Developer Tools",
    "Inspect with Chrome Developer Tools",
];
const EDGE_TITLES: &[&str] = &[
    "Inspect with Edge Developer Tools",
    "Inspect with Microsoft Edge DevTools",
    "Inspect with Edge DevTools",
];
const CHROME_TAB_CLOSE_LABELS: &[&str] = &["Close"];
const EDGE_TAB_CLOSE_LABELS: &[&str] = &["Close tab"];

const CHROME: BrowserSetupDescriptor = BrowserSetupDescriptor {
    product: BrowserProduct::GoogleChrome,
    product_name: "Google Chrome",
    setup_url: "chrome://inspect/#remote-debugging",
    page_titles: CHROME_TITLES,
    page_heading: "Remote debugging",
    checkbox_label: "Allow remote debugging for this browser instance",
    tab_close_labels: CHROME_TAB_CLOSE_LABELS,
};

const CHROMIUM: BrowserSetupDescriptor = BrowserSetupDescriptor {
    product: BrowserProduct::Chromium,
    product_name: "Chromium",
    setup_url: "chrome://inspect/#remote-debugging",
    page_titles: CHROMIUM_TITLES,
    page_heading: "Remote debugging",
    checkbox_label: "Allow remote debugging for this browser instance",
    tab_close_labels: CHROME_TAB_CLOSE_LABELS,
};

const EDGE: BrowserSetupDescriptor = BrowserSetupDescriptor {
    product: BrowserProduct::MicrosoftEdge,
    product_name: "Microsoft Edge",
    setup_url: "edge://inspect/#remote-debugging",
    page_titles: EDGE_TITLES,
    page_heading: "Remote debugging",
    checkbox_label: "Allow remote debugging for this browser instance",
    tab_close_labels: EDGE_TAB_CLOSE_LABELS,
};

pub fn existing_profile_setup_descriptor(
    product: BrowserProduct,
) -> Option<&'static BrowserSetupDescriptor> {
    match product {
        BrowserProduct::GoogleChrome => Some(&CHROME),
        BrowserProduct::Chromium => Some(&CHROMIUM),
        BrowserProduct::MicrosoftEdge => Some(&EDGE),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn setup_is_limited_to_products_with_exact_descriptors() {
        assert_eq!(
            existing_profile_setup_descriptor(BrowserProduct::GoogleChrome)
                .unwrap()
                .setup_url,
            "chrome://inspect/#remote-debugging"
        );
        assert_eq!(
            existing_profile_setup_descriptor(BrowserProduct::MicrosoftEdge)
                .unwrap()
                .setup_url,
            "edge://inspect/#remote-debugging"
        );
        assert_eq!(
            existing_profile_setup_descriptor(BrowserProduct::Chromium)
                .unwrap()
                .product,
            BrowserProduct::Chromium
        );
        for product in [
            BrowserProduct::Brave,
            BrowserProduct::Firefox,
            BrowserProduct::Safari,
            BrowserProduct::Electron,
            BrowserProduct::Other,
        ] {
            assert!(existing_profile_setup_descriptor(product).is_none());
        }
    }
}

//! Trusted host adapter for residual authorization boundaries.
//!
//! The callback is immutable constructor configuration. It is never exposed as
//! a tool and Cua does not prescribe or render a consent interface.

use std::sync::Arc;

use async_trait::async_trait;
use cua_driver_core::consent::{
    ConsentAction, ConsentRequest, ProtectedConsentProvider, ProviderDecision,
};
use thiserror::Error;

#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum DriverAuthorizationAction {
    Allow,
    Deny,
    Cancel,
}

#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct DriverAuthorizationDecision {
    pub action: DriverAuthorizationAction,
    pub request_digest: String,
}

/// Content-bounded request delivered only to trusted host code.
///
/// `resource_json` contains an attested resource identity. Hosts must avoid
/// logging it or forwarding it to a model.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct DriverAuthorizationRequest {
    pub schema: String,
    pub nonce: String,
    pub generation: u64,
    pub daemon_instance: String,
    pub permission_mode: String,
    pub managed_policy_sha256: Option<String>,
    pub user_policy_sha256: Option<String>,
    pub adapter_id: String,
    pub risk_class: String,
    pub public_session: String,
    pub transport_session: String,
    pub resource_json: String,
    pub human_summary: String,
    pub expires_unix_ms: u64,
    pub request_digest: String,
}

#[derive(Debug, Error, uniffi::Error)]
pub enum DriverAuthorizationHostError {
    #[error("authorization host failed: {reason}")]
    Failed { reason: String },
}

/// Optional callback implemented by a trusted embedding application.
///
/// Cua invokes this only for a residual boundary whose active permission mode
/// requires a host grant. Routine standard-mode automation and every
/// in-manifest bounded operation bypass it.
#[uniffi::export(with_foreign)]
#[async_trait]
pub trait DriverAuthorizationHost: Send + Sync {
    async fn authorize(
        &self,
        request: DriverAuthorizationRequest,
    ) -> Result<DriverAuthorizationDecision, DriverAuthorizationHostError>;
}

pub(crate) struct SdkDriverAuthorizationHost {
    host: Arc<dyn DriverAuthorizationHost>,
}

impl SdkDriverAuthorizationHost {
    pub(crate) fn new(host: Arc<dyn DriverAuthorizationHost>) -> Arc<Self> {
        Arc::new(Self { host })
    }

    pub(crate) fn adapt(
        host: Option<Arc<dyn DriverAuthorizationHost>>,
    ) -> Option<Arc<dyn ProtectedConsentProvider>> {
        host.map(|host| Self::new(host) as Arc<dyn ProtectedConsentProvider>)
    }
}

#[async_trait]
impl ProtectedConsentProvider for SdkDriverAuthorizationHost {
    fn provider_id(&self) -> &'static str {
        "trusted_sdk_authorization_host_v1"
    }

    async fn request_consent(&self, request: &ConsentRequest) -> Result<ProviderDecision, String> {
        let decision = self
            .host
            .authorize(export_request(request)?)
            .await
            .map_err(|error| error.to_string())?;
        Ok(ProviderDecision {
            action: match decision.action {
                DriverAuthorizationAction::Allow => ConsentAction::Accept,
                DriverAuthorizationAction::Deny => ConsentAction::Decline,
                DriverAuthorizationAction::Cancel => ConsentAction::Cancel,
            },
            request_digest: decision.request_digest,
        })
    }
}

fn export_request(request: &ConsentRequest) -> Result<DriverAuthorizationRequest, String> {
    Ok(DriverAuthorizationRequest {
        schema: "cua-driver-authorization-request-v1".to_owned(),
        nonce: request.nonce.clone(),
        generation: request.generation,
        daemon_instance: request.daemon_instance.clone(),
        permission_mode: request.permission_mode.as_str().to_owned(),
        managed_policy_sha256: request.managed_policy_sha256.clone(),
        user_policy_sha256: request.user_policy_sha256.clone(),
        adapter_id: request.operation.clone(),
        risk_class: request.risk_class.as_str().to_owned(),
        public_session: request.public_session.clone(),
        transport_session: request.transport_session.clone(),
        resource_json: serde_json::to_string(&request.resource)
            .map_err(|error| format!("could not serialize protected resource: {error}"))?,
        human_summary: request.human_summary.clone(),
        expires_unix_ms: u64::try_from(request.expires_unix_ms).unwrap_or(u64::MAX),
        request_digest: request.request_digest.clone(),
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use cua_driver_core::authorization::{PermissionMode, RiskClass};
    use cua_driver_core::consent::ApprovalBroker;

    struct FakeHost {
        action: DriverAuthorizationAction,
    }

    #[async_trait]
    impl DriverAuthorizationHost for FakeHost {
        async fn authorize(
            &self,
            request: DriverAuthorizationRequest,
        ) -> Result<DriverAuthorizationDecision, DriverAuthorizationHostError> {
            Ok(DriverAuthorizationDecision {
                action: self.action,
                request_digest: request.request_digest,
            })
        }
    }

    fn request(broker: &ApprovalBroker) -> ConsentRequest {
        broker.request(
            PermissionMode::Standard,
            "existing_profile",
            RiskClass::R2,
            "public",
            "transport",
            serde_json::json!({"pid": 42, "window_id": 7}),
            "Attach to Chromium window 7",
        )
    }

    #[tokio::test]
    async fn host_allow_and_deny_map_to_exact_core_decisions() {
        let allowing = SdkDriverAuthorizationHost::new(Arc::new(FakeHost {
            action: DriverAuthorizationAction::Allow,
        }));
        let broker = ApprovalBroker::new(Some(allowing));
        let grant = broker.approve(&request(&broker)).await.unwrap();
        assert!(grant.is_live());
        broker.revoke(&grant).await;
        assert!(!grant.is_live());

        let denying = SdkDriverAuthorizationHost::new(Arc::new(FakeHost {
            action: DriverAuthorizationAction::Deny,
        }));
        let broker = ApprovalBroker::new(Some(denying));
        assert!(matches!(
            broker.approve(&request(&broker)).await,
            Err(cua_driver_core::consent::ConsentError::Declined)
        ));
    }
}

//! Pooled CDP browser-endpoint WebSocket client.
//!
//! v2 demultiplexer: a dedicated reader task owns the receive half of
//! each connection and routes frames by `id` to per-call oneshot
//! channels, while unsolicited events fan out to [`CdpConnection::subscribe`]
//! subscribers in arrival order. This replaces v1's hold-the-socket
//! serialization and is what makes `Target.*` auto-attach (OOPIF child
//! sessions) usable: events emitted before a command's reply are
//! guaranteed to be queued on a subscriber created before the call by
//! the time that call returns.
//!
//! Only loopback `ws://` URLs are accepted: the endpoint is a local
//! browser the platform adapter proved we own, never a remote service.

use std::collections::{HashMap, HashSet};
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::{Arc, Mutex as StdMutex, OnceLock};
use std::time::Duration;

use futures_util::stream::{SplitSink, SplitStream};
use futures_util::{SinkExt, StreamExt};
use serde_json::Value;
use tokio::net::TcpStream;
use tokio::sync::{mpsc, oneshot, Mutex};
use tokio_tungstenite::tungstenite::Message;
use tokio_tungstenite::{MaybeTlsStream, WebSocketStream};

type WsStream = WebSocketStream<MaybeTlsStream<TcpStream>>;

const CALL_TIMEOUT: Duration = Duration::from_secs(20);
const CONNECT_TIMEOUT: Duration = Duration::from_secs(10);

/// Connection-scoped command policy. Grant-owned personal-profile sockets
/// always use the reviewed set below; callers cannot opt out or relax it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CdpMethodPolicy {
    Unrestricted,
    ExistingProfile,
}

const EXISTING_PROFILE_METHODS: &[&str] = &[
    "Accessibility.getFullAXTree",
    "Browser.getWindowBounds",
    "Browser.getWindowForTarget",
    "Browser.setDownloadBehavior",
    "DOM.describeNode",
    "DOM.focus",
    "DOM.getBoxModel",
    "DOM.getDocument",
    "DOM.resolveNode",
    "DOM.scrollIntoViewIfNeeded",
    "DOM.setFileInputFiles",
    "DOMSnapshot.captureSnapshot",
    "Emulation.setFocusEmulationEnabled",
    "Input.dispatchKeyEvent",
    "Input.dispatchMouseEvent",
    "Input.insertText",
    "Page.bringToFront",
    "Page.captureScreenshot",
    "Page.enable",
    "Page.getFrameTree",
    "Page.getLayoutMetrics",
    "Page.handleJavaScriptDialog",
    "Page.navigate",
    "Runtime.callFunctionOn",
    "Runtime.evaluate",
    "Target.activateTarget",
    "Target.attachToTarget",
    "Target.detachFromTarget",
    "Target.getTargets",
    "Target.setAutoAttach",
];

impl CdpMethodPolicy {
    fn allows(self, method: &str) -> bool {
        match self {
            Self::Unrestricted => true,
            Self::ExistingProfile => EXISTING_PROFILE_METHODS.binary_search(&method).is_ok(),
        }
    }
}

/// Validate that `url` is a plain-`ws` loopback WebSocket URL.
/// Anything else — `wss`, remote hosts, hostnames that merely *resolve*
/// to loopback — is rejected; the endpoint contract is a literal
/// loopback address handed over by the platform adapter.
pub fn validate_loopback_ws_url(url: &str) -> Result<(), String> {
    let rest = url
        .strip_prefix("ws://")
        .ok_or_else(|| format!("endpoint URL must use the ws:// scheme: {url}"))?;
    let authority = rest.split('/').next().unwrap_or("");
    let host = if let Some(bracketed) = authority.strip_prefix('[') {
        // [::1]:9222 form.
        bracketed.split(']').next().unwrap_or("")
    } else {
        authority.rsplit_once(':').map_or(authority, |(h, _)| h)
    };
    match host {
        "127.0.0.1" | "::1" | "localhost" => Ok(()),
        other => Err(format!("endpoint host {other:?} is not loopback: {url}")),
    }
}

/// An unsolicited CDP event as delivered by the browser endpoint.
#[derive(Debug, Clone)]
pub struct CdpEvent {
    pub method: String,
    /// The (parent) session the event is scoped to under flattened
    /// sessions, when present.
    pub session_id: Option<String>,
    pub params: Value,
}

/// Bounded state for one page-owned JavaScript dialog. Message text and URLs
/// are deliberately not retained.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CdpDialogState {
    pub generation: u64,
    pub kind: String,
    pub session_id: String,
}

/// What the reader routed back for one in-flight call.
enum CallOutcome {
    Result(Value),
    Error { code: Option<i64>, message: String },
}

/// State shared between the caller side and the reader task.
struct Demux {
    pending: StdMutex<HashMap<u64, oneshot::Sender<CallOutcome>>>,
    subscribers: StdMutex<Vec<mpsc::UnboundedSender<CdpEvent>>>,
    session_targets: StdMutex<HashMap<String, String>>,
    dialogs: StdMutex<HashMap<String, CdpDialogState>>,
    next_dialog_generation: AtomicU64,
    closed: AtomicBool,
}

impl Demux {
    fn close(&self) {
        self.closed.store(true, Ordering::SeqCst);
        // Dropping the senders wakes every pending caller with a recv
        // error, which `call` reports as a closed socket.
        self.pending.lock().unwrap().clear();
        self.subscribers.lock().unwrap().clear();
        self.session_targets.lock().unwrap().clear();
        self.dialogs.lock().unwrap().clear();
    }
}

/// The reader task: routes replies by id, fans events out to
/// subscribers, and fails everything on socket close.
async fn read_loop(mut read: SplitStream<WsStream>, demux: Arc<Demux>) {
    loop {
        let frame = match read.next().await {
            Some(Ok(frame)) => frame,
            Some(Err(_)) | None => break,
        };
        let text = match frame {
            Message::Text(t) => t,
            Message::Close(_) => break,
            _ => continue,
        };
        let v: Value = match serde_json::from_str(&text) {
            Ok(v) => v,
            Err(_) => continue,
        };
        if let Some(id) = v.get("id").and_then(Value::as_u64) {
            let Some(tx) = demux.pending.lock().unwrap().remove(&id) else {
                continue; // reply to a timed-out or unknown call
            };
            let outcome = match v.get("error") {
                Some(err) => CallOutcome::Error {
                    code: err.get("code").and_then(Value::as_i64),
                    message: err
                        .get("message")
                        .and_then(Value::as_str)
                        .unwrap_or("unknown CDP error")
                        .to_owned(),
                },
                None => CallOutcome::Result(v.get("result").cloned().unwrap_or(Value::Null)),
            };
            let _ = tx.send(outcome);
        } else if let Some(method) = v.get("method").and_then(Value::as_str) {
            let event = CdpEvent {
                method: method.to_owned(),
                session_id: v
                    .get("sessionId")
                    .and_then(Value::as_str)
                    .map(str::to_owned),
                params: v.get("params").cloned().unwrap_or(Value::Null),
            };
            if let Some(session_id) = event.session_id.as_deref() {
                let target_id = demux
                    .session_targets
                    .lock()
                    .unwrap()
                    .get(session_id)
                    .cloned();
                match event.method.as_str() {
                    "Page.javascriptDialogOpening" => {
                        let kind = match event.params.get("type").and_then(Value::as_str) {
                            Some("alert") => "alert",
                            Some("confirm") => "confirm",
                            Some("prompt") => "prompt",
                            Some("beforeunload") => "beforeunload",
                            _ => "other",
                        };
                        let generation =
                            demux.next_dialog_generation.fetch_add(1, Ordering::Relaxed);
                        if let Some(target_id) = target_id {
                            demux.dialogs.lock().unwrap().insert(
                                target_id,
                                CdpDialogState {
                                    generation,
                                    kind: kind.to_owned(),
                                    session_id: session_id.to_owned(),
                                },
                            );
                        }
                    }
                    "Page.javascriptDialogClosed" => {
                        if let Some(target_id) = target_id {
                            demux.dialogs.lock().unwrap().remove(&target_id);
                        }
                    }
                    _ => {}
                }
            }
            demux
                .subscribers
                .lock()
                .unwrap()
                .retain(|s| s.send(event.clone()).is_ok());
        }
    }
    demux.close();
}

/// A single browser-endpoint connection.
pub struct CdpConnection {
    writer: Mutex<SplitSink<WsStream, Message>>,
    demux: Arc<Demux>,
    next_id: AtomicU64,
    existing_profile_policy: AtomicBool,
    reader: tokio::task::JoinHandle<()>,
}

impl Drop for CdpConnection {
    fn drop(&mut self) {
        self.reader.abort();
        self.demux.close();
    }
}

impl CdpConnection {
    pub async fn connect(ws_url: &str) -> anyhow::Result<Self> {
        validate_loopback_ws_url(ws_url).map_err(|e| anyhow::anyhow!(e))?;
        let (ws, _resp) =
            tokio::time::timeout(CONNECT_TIMEOUT, tokio_tungstenite::connect_async(ws_url))
                .await
                .map_err(|_| anyhow::anyhow!("CDP connect to {ws_url} timed out"))??;
        let (write, read) = ws.split();
        let demux = Arc::new(Demux {
            pending: StdMutex::new(HashMap::new()),
            subscribers: StdMutex::new(Vec::new()),
            session_targets: StdMutex::new(HashMap::new()),
            dialogs: StdMutex::new(HashMap::new()),
            next_dialog_generation: AtomicU64::new(1),
            closed: AtomicBool::new(false),
        });
        let reader = tokio::spawn(read_loop(read, demux.clone()));
        Ok(Self {
            writer: Mutex::new(write),
            demux,
            next_id: AtomicU64::new(1),
            existing_profile_policy: AtomicBool::new(false),
            reader,
        })
    }

    pub fn method_policy(&self) -> CdpMethodPolicy {
        if self.existing_profile_policy.load(Ordering::SeqCst) {
            CdpMethodPolicy::ExistingProfile
        } else {
            CdpMethodPolicy::Unrestricted
        }
    }

    /// Monotonic restriction: once a socket is claimed for a personal
    /// profile it can never return to the unrestricted command surface.
    pub fn restrict_to_existing_profile(&self) {
        self.existing_profile_policy.store(true, Ordering::SeqCst);
    }

    /// Whether the reader observed the socket close. A closed connection
    /// never recovers; the pool redials.
    pub fn is_closed(&self) -> bool {
        self.demux.closed.load(Ordering::SeqCst)
    }

    /// Subscribe to unsolicited CDP events. Delivery is in socket
    /// arrival order, and any event the endpoint emitted before a
    /// command's reply is already queued here by the time [`Self::call`]
    /// for that command returns — callers can drain with `try_recv`
    /// deterministically (the Target.setAutoAttach pattern).
    pub fn subscribe(&self) -> mpsc::UnboundedReceiver<CdpEvent> {
        let (tx, rx) = mpsc::unbounded_channel();
        self.demux.subscribers.lock().unwrap().push(tx);
        rx
    }

    /// Associate the one Page-enabled dialog session with its exact target.
    /// Later calls may use fresh attachment sessions, but dialog events keep
    /// arriving on this bounded, persistent event session.
    pub fn register_dialog_session(&self, session_id: &str, target_id: &str) {
        let mut sessions = self.demux.session_targets.lock().unwrap();
        sessions.retain(|_, mapped_target| mapped_target != target_id);
        sessions.insert(session_id.to_owned(), target_id.to_owned());
    }

    pub fn unregister_dialog_session(&self, session_id: &str, target_id: &str) {
        let mut sessions = self.demux.session_targets.lock().unwrap();
        if sessions.get(session_id).map(String::as_str) == Some(target_id) {
            sessions.remove(session_id);
        }
    }

    pub fn has_dialog_session(&self, target_id: &str) -> bool {
        self.demux
            .session_targets
            .lock()
            .unwrap()
            .values()
            .any(|mapped_target| mapped_target == target_id)
    }

    pub fn dialog_state(&self, target_id: &str) -> Option<CdpDialogState> {
        self.demux.dialogs.lock().unwrap().get(target_id).cloned()
    }

    pub fn clear_dialog_state(&self, target_id: &str, generation: u64) {
        let mut dialogs = self.demux.dialogs.lock().unwrap();
        if dialogs.get(target_id).map(|state| state.generation) == Some(generation) {
            dialogs.remove(target_id);
        }
    }

    /// Issue one CDP command and await its `id`-matched reply.
    /// `session_id` targets an attached (flattened) target session.
    /// Returns the `result` object, or an error carrying the CDP
    /// `error.code` (as `({code})`) and `error.message`.
    pub async fn call(
        &self,
        session_id: Option<&str>,
        method: &str,
        params: Value,
    ) -> anyhow::Result<Value> {
        let policy = self.method_policy();
        if !policy.allows(method) {
            anyhow::bail!(
                "existing-profile CDP policy refused method {method}; the reviewed personal-profile command set cannot be bypassed"
            );
        }
        if self.is_closed() {
            anyhow::bail!("CDP socket closed before {method}");
        }
        let id = self.next_id.fetch_add(1, Ordering::Relaxed);
        let (tx, rx) = oneshot::channel();
        self.demux.pending.lock().unwrap().insert(id, tx);
        // Close can race the initial check. If the reader cleared the
        // pending map just before this insertion, remove the orphaned
        // sender now instead of waiting for the call timeout.
        if self.is_closed() {
            self.demux.pending.lock().unwrap().remove(&id);
            anyhow::bail!("CDP socket closed before {method}");
        }

        let mut msg = serde_json::json!({ "id": id, "method": method, "params": params });
        if let Some(sid) = session_id {
            msg["sessionId"] = Value::String(sid.to_owned());
        }
        let sent = {
            let mut writer = self.writer.lock().await;
            writer.send(Message::Text(msg.to_string())).await
        };
        if let Err(e) = sent {
            self.demux.pending.lock().unwrap().remove(&id);
            anyhow::bail!("CDP send failed during {method}: {e}");
        }

        match tokio::time::timeout(CALL_TIMEOUT, rx).await {
            Err(_) => {
                self.demux.pending.lock().unwrap().remove(&id);
                anyhow::bail!("CDP {method} timed out after {CALL_TIMEOUT:?}")
            }
            Ok(Err(_)) => anyhow::bail!("CDP socket closed during {method}"),
            Ok(Ok(CallOutcome::Result(v))) => Ok(v),
            Ok(Ok(CallOutcome::Error {
                code: Some(code),
                message,
            })) => anyhow::bail!("CDP {method} failed ({code}): {message}"),
            Ok(Ok(CallOutcome::Error {
                code: None,
                message,
            })) => anyhow::bail!("CDP {method} failed: {message}"),
        }
    }
}

#[derive(Clone)]
struct PoolEntry {
    conn: Arc<CdpConnection>,
    generation: Option<u64>,
}

fn claimed_ports() -> &'static StdMutex<HashMap<u16, usize>> {
    static CLAIMED: OnceLock<StdMutex<HashMap<u16, usize>>> = OnceLock::new();
    CLAIMED.get_or_init(|| StdMutex::new(HashMap::new()))
}

fn loopback_port(url: &str) -> Option<u16> {
    let rest = url.strip_prefix("ws://")?;
    let authority = rest.split('/').next()?;
    if let Some(bracketed) = authority.strip_prefix('[') {
        return bracketed.split_once("]:")?.1.parse().ok();
    }
    authority.rsplit_once(':')?.1.parse().ok()
}

/// Whether an existing-profile grant owns the DevTools listener used by this
/// URL. The legacy page route consults this before opening its own page socket.
pub fn endpoint_port_is_grant_owned(url: &str) -> bool {
    loopback_port(url).is_some_and(|port| claimed_ports().lock().unwrap().contains_key(&port))
}

/// One pooled browser-level connection per endpoint URL. Existing-profile
/// entries are additionally owned by one explicit connection generation.
pub struct CdpPool {
    conns: Mutex<HashMap<String, PoolEntry>>,
    claimed_loopback_ports: StdMutex<HashSet<u16>>,
}

impl CdpPool {
    pub fn new() -> Self {
        Self {
            conns: Mutex::new(HashMap::new()),
            claimed_loopback_ports: StdMutex::new(HashSet::new()),
        }
    }

    /// Get the pooled connection for `ws_url`, dialing if needed.
    /// A connection whose socket closed is replaced transparently.
    pub async fn get(&self, ws_url: &str) -> anyhow::Result<Arc<CdpConnection>> {
        if endpoint_port_is_grant_owned(ws_url) {
            anyhow::bail!(
                "this DevTools endpoint is owned by a first-class existing-profile attachment"
            );
        }
        let mut conns = self.conns.lock().await;
        if let Some(existing) = conns.get(ws_url) {
            if existing.generation.is_some() {
                anyhow::bail!("this DevTools endpoint is owned by an attachment generation");
            }
            if !existing.conn.is_closed() {
                return Ok(existing.conn.clone());
            }
            conns.remove(ws_url);
        }
        let conn = Arc::new(CdpConnection::connect(ws_url).await?);
        conns.insert(
            ws_url.to_owned(),
            PoolEntry {
                conn: conn.clone(),
                generation: None,
            },
        );
        Ok(conn)
    }

    /// Convert the one live browser-level socket into grant-owned state. This
    /// does not redial and therefore cannot create a second consent prompt.
    pub async fn claim_existing(
        &self,
        ws_url: &str,
        generation: u64,
    ) -> anyhow::Result<Arc<CdpConnection>> {
        let port = loopback_port(ws_url)
            .ok_or_else(|| anyhow::anyhow!("existing-profile endpoint has no loopback port"))?;
        let mut conns = self.conns.lock().await;
        let conn = match conns.get(ws_url) {
            Some(entry) if !entry.conn.is_closed() => entry.conn.clone(),
            Some(_) => anyhow::bail!("the approved browser socket closed before it was claimed"),
            None => Arc::new(CdpConnection::connect(ws_url).await?),
        };
        conn.restrict_to_existing_profile();
        conns.insert(
            ws_url.to_owned(),
            PoolEntry {
                conn: conn.clone(),
                generation: Some(generation),
            },
        );
        if self.claimed_loopback_ports.lock().unwrap().insert(port) {
            *claimed_ports().lock().unwrap().entry(port).or_default() += 1;
        }
        Ok(conn)
    }

    /// Reuse only the socket belonging to the exact live grant generation.
    /// Closed sockets are not replaced here; reconnect is an explicit state
    /// transition owned by the browser engine.
    pub async fn get_existing(
        &self,
        ws_url: &str,
        generation: u64,
    ) -> anyhow::Result<Arc<CdpConnection>> {
        let conns = self.conns.lock().await;
        let entry = conns
            .get(ws_url)
            .ok_or_else(|| anyhow::anyhow!("the grant-owned browser socket is missing"))?;
        if entry.generation != Some(generation) {
            anyhow::bail!("the browser socket belongs to a different connection generation");
        }
        if entry.conn.is_closed() {
            anyhow::bail!("the grant-owned browser socket is closed");
        }
        Ok(entry.conn.clone())
    }

    /// Replace one dead grant-owned socket with exactly one new generation.
    pub async fn reconnect_existing(
        &self,
        ws_url: &str,
        old_generation: u64,
        new_generation: u64,
    ) -> anyhow::Result<Arc<CdpConnection>> {
        {
            let conns = self.conns.lock().await;
            if let Some(entry) = conns.get(ws_url) {
                if entry
                    .generation
                    .is_some_and(|generation| generation > old_generation)
                {
                    anyhow::bail!("the reconnect source generation is no longer current");
                }
                if entry.generation == Some(old_generation) && !entry.conn.is_closed() {
                    return Ok(entry.conn.clone());
                }
            }
        }

        // A WebSocket handshake can wait for browser-owned consent UI. Never
        // hold the pool mutex across that wait: grant revocation must remain
        // able to remove the old generation when consent is refused.
        let conn = Arc::new(CdpConnection::connect(ws_url).await?);
        conn.restrict_to_existing_profile();
        let mut conns = self.conns.lock().await;
        if let Some(entry) = conns.get(ws_url) {
            if entry
                .generation
                .is_some_and(|generation| generation > old_generation)
            {
                if entry.generation == Some(new_generation) && !entry.conn.is_closed() {
                    return Ok(entry.conn.clone());
                }
                anyhow::bail!("the reconnect source generation is no longer current");
            }
        }
        conns.insert(
            ws_url.to_owned(),
            PoolEntry {
                conn: conn.clone(),
                generation: Some(new_generation),
            },
        );
        Ok(conn)
    }

    /// Drop a (likely dead) connection so the next call redials.
    pub async fn evict(&self, ws_url: &str) {
        self.conns.lock().await.remove(ws_url);
    }

    pub fn release_claim_marker(&self, ws_url: &str) {
        if let Some(port) = loopback_port(ws_url) {
            if self.claimed_loopback_ports.lock().unwrap().remove(&port) {
                release_claimed_port(port);
            }
        }
    }

    pub async fn release_existing(&self, ws_url: &str, generation: u64) {
        let mut conns = self.conns.lock().await;
        if conns
            .get(ws_url)
            .is_some_and(|entry| entry.generation == Some(generation))
        {
            conns.remove(ws_url);
        }
        drop(conns);
        self.release_claim_marker(ws_url);
    }
}

impl Default for CdpPool {
    fn default() -> Self {
        Self::new()
    }
}

impl Drop for CdpPool {
    fn drop(&mut self) {
        let claimed_loopback_ports = self.claimed_loopback_ports.get_mut().unwrap();
        if claimed_loopback_ports.is_empty() {
            return;
        }
        let mut global = claimed_ports().lock().unwrap();
        for port in claimed_loopback_ports.drain() {
            if let Some(count) = global.get_mut(&port) {
                *count -= 1;
                if *count == 0 {
                    global.remove(&port);
                }
            }
        }
    }
}

fn release_claimed_port(port: u16) {
    let mut global = claimed_ports().lock().unwrap();
    if let Some(count) = global.get_mut(&port) {
        *count -= 1;
        if *count == 0 {
            global.remove(&port);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::browser::mock_cdp::{MockCdpServer, MockEvent, MockReply};
    use serde_json::json;
    use std::sync::Arc as StdArc;

    #[test]
    fn loopback_urls_are_accepted() {
        for ok in [
            "ws://127.0.0.1:9222/devtools/browser/abc",
            "ws://localhost:9222/devtools/browser/abc",
            "ws://[::1]:9222/devtools/browser/abc",
            "ws://127.0.0.1/devtools/browser/abc",
        ] {
            assert!(validate_loopback_ws_url(ok).is_ok(), "{ok}");
        }
    }

    #[test]
    fn non_loopback_and_non_ws_urls_are_rejected() {
        for bad in [
            "wss://127.0.0.1:9222/devtools/browser/abc",
            "http://127.0.0.1:9222/json",
            "ws://10.0.0.5:9222/devtools/browser/abc",
            "ws://example.com:9222/devtools/browser/abc",
            "ws://127.0.0.1.evil.test:9222/x",
            "ws://[fe80::1]:9222/x",
            "",
        ] {
            assert!(validate_loopback_ws_url(bad).is_err(), "{bad}");
        }
    }

    #[tokio::test]
    async fn call_returns_the_id_matched_result() {
        let server = MockCdpServer::start(StdArc::new(|call| {
            assert_eq!(call.method, "Echo.params");
            MockReply::ok(json!({ "echoed": call.params.clone() }))
        }))
        .await;
        let conn = CdpConnection::connect(&server.ws_url()).await.unwrap();
        let result = conn
            .call(None, "Echo.params", json!({ "x": 7 }))
            .await
            .unwrap();
        assert_eq!(result["echoed"]["x"], 7);
    }

    #[tokio::test]
    async fn claimed_existing_profile_socket_is_generation_owned() {
        let server = MockCdpServer::start(StdArc::new(|_| MockReply::ok(json!({})))).await;
        let url = server.ws_url();
        let pool = CdpPool::new();
        let initial = pool.get(&url).await.unwrap();
        let claimed = pool.claim_existing(&url, 1).await.unwrap();
        assert!(Arc::ptr_eq(&initial, &claimed), "claim must not redial");
        assert_eq!(
            claimed.method_policy(),
            CdpMethodPolicy::ExistingProfile,
            "claiming a personal-profile socket must restrict it in place"
        );
        assert!(pool.get(&url).await.is_err(), "legacy access must refuse");
        assert!(pool.get_existing(&url, 2).await.is_err());
        let reused = pool.get_existing(&url, 1).await.unwrap();
        assert!(Arc::ptr_eq(&claimed, &reused));
        pool.release_existing(&url, 1).await;
        assert!(
            pool.get(&url).await.is_ok(),
            "session cleanup releases ownership"
        );
    }

    #[tokio::test]
    async fn existing_profile_policy_rejects_fingerprint_and_interception_methods() {
        let seen = StdArc::new(StdMutex::new(Vec::<String>::new()));
        let server_seen = seen.clone();
        let server = MockCdpServer::start(StdArc::new(move |call| {
            server_seen.lock().unwrap().push(call.method.clone());
            MockReply::ok(json!({}))
        }))
        .await;
        let conn = CdpConnection::connect(&server.ws_url()).await.unwrap();
        conn.restrict_to_existing_profile();

        for method in [
            "Runtime.enable",
            "Target.setDiscoverTargets",
            "Page.addScriptToEvaluateOnNewDocument",
            "Network.enable",
            "Fetch.enable",
            "Emulation.setUserAgentOverride",
            "Emulation.setDeviceMetricsOverride",
            "Emulation.setTimezoneOverride",
        ] {
            let error = conn.call(None, method, json!({})).await.unwrap_err();
            assert!(
                error.to_string().contains("policy refused"),
                "{method}: {error}"
            );
        }
        assert!(
            seen.lock().unwrap().is_empty(),
            "refused methods must not reach the browser socket"
        );

        conn.call(None, "Target.getTargets", json!({}))
            .await
            .expect("reviewed method remains available");
        assert_eq!(&*seen.lock().unwrap(), &["Target.getTargets"]);
    }

    #[tokio::test]
    async fn dropping_a_pool_releases_its_claim_marker() {
        let server = MockCdpServer::start(StdArc::new(|_| MockReply::ok(json!({})))).await;
        let url = server.ws_url();
        {
            let pool = CdpPool::new();
            pool.claim_existing(&url, 1).await.unwrap();
            assert!(endpoint_port_is_grant_owned(&url));
        }
        assert!(!endpoint_port_is_grant_owned(&url));
    }

    #[tokio::test]
    async fn claim_marker_is_reference_counted_across_pools() {
        let server = MockCdpServer::start(StdArc::new(|_| MockReply::ok(json!({})))).await;
        let url = server.ws_url();
        let first = CdpPool::new();
        let second = CdpPool::new();
        first.claim_existing(&url, 1).await.unwrap();
        second.claim_existing(&url, 2).await.unwrap();

        drop(first);
        assert!(endpoint_port_is_grant_owned(&url));
        drop(second);
        assert!(!endpoint_port_is_grant_owned(&url));
    }

    #[tokio::test]
    async fn stalled_reconnect_does_not_block_generation_release() {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let port = listener.local_addr().unwrap().port();
        let server = tokio::spawn(async move {
            let (first, _) = listener.accept().await.unwrap();
            let _first_ws = tokio_tungstenite::accept_async(first).await.unwrap();
            let (_stalled_reconnect, _) = listener.accept().await.unwrap();
            tokio::time::sleep(std::time::Duration::from_secs(10)).await;
        });
        let url = format!("ws://127.0.0.1:{port}/devtools/browser/reconnect");
        let pool = CdpPool::new();
        let claimed = pool.claim_existing(&url, 1).await.unwrap();
        claimed.demux.close();

        let mut reconnect = Box::pin(pool.reconnect_existing(&url, 1, 2));
        tokio::select! {
            _ = &mut reconnect => panic!("reconnect unexpectedly completed"),
            _ = tokio::time::sleep(std::time::Duration::from_millis(100)) => {}
        }
        tokio::time::timeout(
            std::time::Duration::from_millis(500),
            pool.release_existing(&url, 1),
        )
        .await
        .expect("grant release must not wait for the reconnect handshake");
        drop(reconnect);
        server.abort();
    }

    #[tokio::test]
    async fn cdp_error_codes_are_preserved_in_the_message() {
        let server = MockCdpServer::start(StdArc::new(|_| {
            MockReply::method_not_found("Target.setAutoAttach")
        }))
        .await;
        let conn = CdpConnection::connect(&server.ws_url()).await.unwrap();
        let err = conn
            .call(Some("sess-1"), "Target.setAutoAttach", json!({}))
            .await
            .unwrap_err();
        let msg = err.to_string();
        assert!(msg.contains("(-32601)"), "{msg}");
        assert!(msg.contains("Target.setAutoAttach"), "{msg}");
    }

    #[tokio::test]
    async fn events_emitted_before_a_reply_are_drainable_after_the_call() {
        let server = MockCdpServer::start(StdArc::new(|call| {
            if call.method == "Emitter.go" {
                MockReply::ok(json!({})).with_events(vec![
                    MockEvent {
                        method: "Thing.happened".into(),
                        session_id: None,
                        params: json!({ "n": 1 }),
                    },
                    MockEvent {
                        method: "Thing.happened".into(),
                        session_id: Some("child-sess".into()),
                        params: json!({ "n": 2 }),
                    },
                ])
            } else {
                MockReply::ok(json!({}))
            }
        }))
        .await;
        let conn = CdpConnection::connect(&server.ws_url()).await.unwrap();
        let mut events = conn.subscribe();
        conn.call(None, "Emitter.go", json!({})).await.unwrap();

        // The demux guarantees pre-reply events are queued: no awaiting.
        let first = events.try_recv().expect("first event queued");
        assert_eq!(first.method, "Thing.happened");
        assert_eq!(first.session_id, None);
        assert_eq!(first.params["n"], 1);
        let second = events.try_recv().expect("second event queued");
        assert_eq!(second.session_id.as_deref(), Some("child-sess"));
        assert_eq!(second.params["n"], 2);
        assert!(events.try_recv().is_err(), "no phantom events");
    }

    #[tokio::test]
    async fn javascript_dialog_journal_is_bounded_and_generation_checked() {
        let server = MockCdpServer::start(StdArc::new(|call| match call.method.as_str() {
            "Dialog.open" => MockReply::ok(json!({})).with_events(vec![MockEvent {
                method: "Page.javascriptDialogOpening".into(),
                session_id: call.session_id.clone(),
                params: json!({
                    "type": "prompt",
                    "message": "private dialog text",
                    "url": "https://private.example"
                }),
            }]),
            "Dialog.close" => MockReply::ok(json!({})).with_events(vec![MockEvent {
                method: "Page.javascriptDialogClosed".into(),
                session_id: call.session_id.clone(),
                params: json!({}),
            }]),
            _ => MockReply::ok(json!({})),
        }))
        .await;
        let conn = CdpConnection::connect(&server.ws_url()).await.unwrap();
        conn.register_dialog_session("tab-session-a", "page-target");
        conn.call(Some("tab-session-a"), "Dialog.open", json!({}))
            .await
            .unwrap();
        let dialog = conn.dialog_state("page-target").expect("dialog journaled");
        assert_eq!(dialog.kind, "prompt");
        assert_eq!(dialog.session_id, "tab-session-a");
        assert!(!format!("{dialog:?}").contains("private"));
        conn.call(Some("tab-session-a"), "Dialog.close", json!({}))
            .await
            .unwrap();
        assert!(conn.dialog_state("page-target").is_none());
    }

    #[tokio::test]
    async fn out_of_order_replies_route_to_the_right_callers() {
        // Raw server: read two requests, reply to the SECOND first.
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let port = listener.local_addr().unwrap().port();
        tokio::spawn(async move {
            let (stream, _) = listener.accept().await.unwrap();
            let mut ws = tokio_tungstenite::accept_async(stream).await.unwrap();
            let mut ids = Vec::new();
            while ids.len() < 2 {
                if let Some(Ok(Message::Text(text))) = ws.next().await {
                    let v: Value = serde_json::from_str(&text).unwrap();
                    ids.push(v["id"].as_u64().unwrap());
                }
            }
            for id in ids.iter().rev() {
                let reply = json!({ "id": id, "result": { "for_id": id } });
                ws.send(Message::Text(reply.to_string())).await.unwrap();
            }
        });

        let conn = CdpConnection::connect(&format!("ws://127.0.0.1:{port}/devtools/browser/x"))
            .await
            .unwrap();
        let (a, b) = tokio::join!(
            conn.call(None, "First.call", json!({})),
            conn.call(None, "Second.call", json!({})),
        );
        let (a, b) = (a.unwrap(), b.unwrap());
        assert_ne!(a["for_id"], b["for_id"]);
        assert_eq!(a["for_id"], 1, "first call gets the id-1 payload");
        assert_eq!(b["for_id"], 2, "second call gets the id-2 payload");
    }

    #[tokio::test]
    async fn socket_close_fails_pending_calls_and_marks_the_connection() {
        // Raw server: accept, read one request, close without replying.
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let port = listener.local_addr().unwrap().port();
        tokio::spawn(async move {
            let (stream, _) = listener.accept().await.unwrap();
            let mut ws = tokio_tungstenite::accept_async(stream).await.unwrap();
            let _ = ws.next().await;
            let _ = ws.close(None).await;
        });

        let conn = CdpConnection::connect(&format!("ws://127.0.0.1:{port}/devtools/browser/x"))
            .await
            .unwrap();
        let err = conn
            .call(None, "Never.replies", json!({}))
            .await
            .unwrap_err();
        assert!(err.to_string().contains("closed"), "{err}");
        assert!(conn.is_closed());
        let err = conn.call(None, "After.close", json!({})).await.unwrap_err();
        assert!(err.to_string().contains("closed"), "{err}");
    }

    #[tokio::test]
    async fn pool_replaces_closed_connections() {
        let server = MockCdpServer::start(StdArc::new(|_| MockReply::ok(json!({})))).await;
        let url = server.ws_url();
        let pool = CdpPool::new();
        let first = pool.get(&url).await.unwrap();
        first.demux.close(); // simulate a dead socket
        let second = pool.get(&url).await.unwrap();
        assert!(
            !StdArc::ptr_eq(&first, &second),
            "pool must redial a closed connection"
        );
        second.call(None, "Ping.pong", json!({})).await.unwrap();
    }
}

//! Legacy-compatible CDP client for Electron and other Chromium apps.
//! HTTP discovery stays compatible with the page tool; WebSocket calls use
//! cua-driver-core's shared event-aware `CdpConnection` transport.

use cua_driver_core::browser::cdp_ws::CdpConnection;
use std::collections::HashMap;
use std::sync::Arc;
use std::time::Duration;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::sync::Mutex as AsyncMutex;

pub struct CdpClient;

impl CdpClient {
    /// Returns true if a CDP endpoint is listening on `port`.
    pub async fn is_available(port: u16) -> bool {
        http_get_json(port).await.is_ok()
    }

    /// Scan the given ports and return the first one that has a "page" target.
    pub async fn find_page_target(ports: &[u16]) -> Option<u16> {
        for &port in ports {
            if let Ok(json) = http_get_json(port).await {
                if let Ok(arr) = serde_json::from_str::<serde_json::Value>(&json) {
                    if let Some(list) = arr.as_array() {
                        let has_page = list
                            .iter()
                            .any(|t| t.get("type").and_then(|v| v.as_str()) == Some("page"));
                        if has_page {
                            return Some(port);
                        }
                    }
                }
            }
        }
        None
    }

    /// Find a live CDP endpoint already listening on one of `pid`'s open TCP
    /// ports (e.g. because the app was launched with a debugging port).
    /// Unlike `find_page_target`, this doesn't guess at a fixed port list —
    /// it only sees ports the process itself opened. Callers that need to
    /// *activate* an inspector that isn't already listening (e.g. Electron's
    /// SIGUSR1 trick) do that themselves before falling back to this.
    ///
    /// Reuses `find_page_target`'s validation (parses the `/json` body and
    /// requires an actual "page" target) rather than the bare TCP-connect
    /// check `is_available` does — a port that merely accepts a connection
    /// and closes it (any number of unrelated local services do this) would
    /// otherwise pass as "available" with an empty, non-CDP response.
    ///
    /// Note: this specifically requires the classic `/json` HTTP discovery
    /// to work, so it won't find a port only reachable via the browser-level
    /// `devtools/browser` endpoint (see `CdpSession::connect`) — callers that
    /// already know the port (e.g. the user enabled `chrome://inspect`
    /// manually) don't need this lookup at all.
    pub async fn find_port_for_pid(pid: i32) -> Option<u16> {
        let ports = listening_ports(pid).await;
        Self::find_page_target(&ports).await
    }

    /// Evaluate JavaScript via CDP Runtime.evaluate on the first page target.
    /// Always opens a fresh connection — used only by the Electron inspector
    /// path (SIGUSR1-activated V8 inspector), which doesn't show the
    /// "Allow remote debugging?" confirmation the Chrome-toggle path does,
    /// so there's no reason to route it through `CdpSessionCache`.
    pub async fn evaluate(javascript: &str, port: u16) -> anyhow::Result<String> {
        let mut session = CdpSession::connect(port, None).await?;
        do_evaluate(&mut session, javascript).await
    }
}

/// Caches one open `CdpSession` per port across calls, instead of opening a
/// fresh WebSocket connection every time.
///
/// This exists because Chrome's own "allow remote debugging" toggle
/// (`chrome://inspect/#remote-debugging`, the only way to reach a user's
/// real/default profile — see `resolve_cdp_port` in `tools/page.rs`) pops up
/// a live "Allow remote debugging?" confirmation on every *new* WebSocket
/// connection to the browser endpoint — confirmed by testing live,
/// repeatedly, against a real Chrome session: three separate
/// `insert_text`/`type_keystrokes` calls, each opening its own connection,
/// each got its own popup. Reusing one already-approved connection across
/// calls (re-attaching to a different tab on it via `Target.getTargets` +
/// `Target.attachToTarget` when needed, never opening a new socket) avoids
/// re-triggering that popup for anything but the very first call after a
/// fresh Chrome launch.
pub struct CdpSessionCache {
    sessions: AsyncMutex<HashMap<u16, Arc<AsyncMutex<CdpSession>>>>,
}

impl CdpSessionCache {
    pub fn new() -> Self {
        Self {
            sessions: AsyncMutex::new(HashMap::new()),
        }
    }

    async fn get_or_connect(
        &self,
        port: u16,
        target_url_contains: Option<&str>,
    ) -> anyhow::Result<Arc<AsyncMutex<CdpSession>>> {
        let mut map = self.sessions.lock().await;
        if let Some(existing) = map.get(&port) {
            return Ok(existing.clone());
        }
        let session = CdpSession::connect(port, target_url_contains).await?;
        let arc = Arc::new(AsyncMutex::new(session));
        map.insert(port, arc.clone());
        Ok(arc)
    }

    async fn evict(&self, port: u16) {
        self.sessions.lock().await.remove(&port);
    }

    /// Evaluate JavaScript against the unique page target selected by
    /// `target_url_contains`, reusing the cached browser connection. This
    /// avoids re-triggering Chrome's "Allow remote debugging?" confirmation
    /// for every targeted page action.
    pub async fn evaluate(
        &self,
        javascript: &str,
        port: u16,
        target_url_contains: Option<&str>,
    ) -> anyhow::Result<String> {
        let arc = self.get_or_connect(port, target_url_contains).await?;
        {
            let mut session = arc.lock().await;
            if session
                .ensure_target(port, target_url_contains)
                .await
                .is_ok()
            {
                return do_evaluate(&mut session, javascript).await;
            }
        }

        self.evict(port).await;
        let arc = self.get_or_connect(port, target_url_contains).await?;
        let mut session = arc.lock().await;
        session.ensure_target(port, target_url_contains).await?;
        do_evaluate(&mut session, javascript).await
    }

    /// Insert `text` at whatever currently holds DOM focus, via CDP's native
    /// `Input.insertText` — a single call, no synthesized keydown/char/keyup
    /// sequence. Chrome's renderer handles this the same way it handles an
    /// IME composition commit, which most rich-text editors (having to
    /// support CJK/IME input regardless) already treat as real input — so
    /// it lands more durably than a JS-level DOM write, at a fraction of the
    /// cost of `dispatch_keystrokes`. It does skip actual key events though,
    /// so page-level keydown/keyup handlers never fire; reach for
    /// `dispatch_keystrokes` instead if an editor's own keyboard shortcuts or
    /// per-keystroke validation need to see real keys.
    ///
    /// Caller must already have focused the target element.
    /// `target_url_contains`, when given, picks the page target whose URL
    /// contains this substring instead of just whichever tab is currently
    /// attached — a browser with more than one tab open has no other way to
    /// know which one the caller means (CDP target ids have no relation to
    /// a window_id).
    pub async fn insert_text(
        &self,
        text: &str,
        port: u16,
        target_url_contains: Option<&str>,
    ) -> anyhow::Result<()> {
        let arc = self.get_or_connect(port, target_url_contains).await?;
        let first_attempt = {
            let mut session = arc.lock().await;
            match session.ensure_target(port, target_url_contains).await {
                Ok(()) => do_insert_text(&mut session, text).await,
                Err(e) => Err(e),
            }
        };
        if first_attempt.is_ok() {
            return first_attempt;
        }

        // Stale/closed connection — evict and retry once against a fresh
        // session, so a dead cache entry self-heals instead of wedging
        // every future call.
        self.evict(port).await;
        let arc = self.get_or_connect(port, target_url_contains).await?;
        let mut session = arc.lock().await;
        session.ensure_target(port, target_url_contains).await?;
        do_insert_text(&mut session, text).await
    }

    /// Type `text` into whatever currently holds DOM focus, via per-character
    /// `Input.dispatchKeyEvent` (keyDown -> char -> keyUp). The `char`
    /// event's `text` field is what actually inserts the character;
    /// bracketing it with keyDown/keyUp gives the page's own keydown/keyup
    /// listeners a real event to see.
    ///
    /// This exists because rich-text editors (React/Draft.js-style
    /// contenteditable) reconcile their own state and can silently discard a
    /// one-shot DOM write (`execCommand`, `innerText =`) on the next render —
    /// a per-character keystroke stream is what those editors' own input
    /// pipeline actually observes as durable.
    ///
    /// Caller must already have focused the target element (e.g. via a prior
    /// click) — this dispatches to whatever element currently has focus, the
    /// same as a hardware keyboard would. `target_url_contains` — see
    /// `insert_text`.
    pub async fn dispatch_keystrokes(
        &self,
        text: &str,
        port: u16,
        target_url_contains: Option<&str>,
    ) -> anyhow::Result<()> {
        let arc = self.get_or_connect(port, target_url_contains).await?;
        let first_attempt = {
            let mut session = arc.lock().await;
            match session.ensure_target(port, target_url_contains).await {
                Ok(()) => do_dispatch_keystrokes(&mut session, text).await,
                Err(e) => Err(e),
            }
        };
        if first_attempt.is_ok() {
            return first_attempt;
        }

        self.evict(port).await;
        let arc = self.get_or_connect(port, target_url_contains).await?;
        let mut session = arc.lock().await;
        session.ensure_target(port, target_url_contains).await?;
        do_dispatch_keystrokes(&mut session, text).await
    }
}

impl Default for CdpSessionCache {
    fn default() -> Self {
        Self::new()
    }
}

async fn do_evaluate(session: &mut CdpSession, javascript: &str) -> anyhow::Result<String> {
    let obj = tokio::time::timeout(
        Duration::from_secs(10),
        session.call(
            "Runtime.evaluate",
            serde_json::json!({
                "expression": javascript,
                "returnByValue": true,
                "awaitPromise": true
            }),
        ),
    )
    .await
    .map_err(|_| anyhow::anyhow!("CDP evaluate timed out after 10s"))??;

    parse_cdp_result(&obj)
}

async fn do_insert_text(session: &mut CdpSession, text: &str) -> anyhow::Result<()> {
    tokio::time::timeout(
        Duration::from_secs(10),
        session.call("Input.insertText", serde_json::json!({ "text": text })),
    )
    .await
    .map_err(|_| anyhow::anyhow!("CDP insertText timed out after 10s"))??;
    Ok(())
}

async fn do_dispatch_keystrokes(session: &mut CdpSession, text: &str) -> anyhow::Result<()> {
    tokio::time::timeout(Duration::from_secs(30), async {
        for ch in text.chars() {
            let key = ch.to_string();
            for event_type in ["keyDown", "char", "keyUp"] {
                // Only the `char` event carries `text`/`unmodifiedText` —
                // that's what actually inserts the character. Chrome
                // treats a non-empty `text` on `keyDown` as ALSO
                // producing input, so setting it on both double-types
                // every character (confirmed: "hello" -> "hheelllloo").
                let mut params = serde_json::json!({
                    "type": event_type,
                    "key": key,
                });
                if event_type == "char" {
                    params["text"] = serde_json::json!(key);
                    params["unmodifiedText"] = serde_json::json!(key);
                }
                session.call("Input.dispatchKeyEvent", params).await?;
            }
            // Small gap between characters — a real keyboard doesn't emit
            // 36 events in the same tick, and some editors' autosave /
            // hashtag-parsing debounce keys off discrete keystrokes.
            tokio::time::sleep(Duration::from_millis(15)).await;
        }
        Ok(())
    })
    .await
    .map_err(|_| anyhow::anyhow!("CDP keystroke dispatch timed out after 30s"))?
}

/// An open CDP connection scoped to one page target, plus whatever session
/// routing that required.
///
/// Two ways to reach a page:
/// - **Classic** — the target's own `webSocketDebuggerUrl` from `/json`.
///   Every message goes straight to that page; no session id needed. This is
///   what a normal `--remote-debugging-port` launch gives you.
/// - **Browser-attached** — connect to the browser-level
///   `ws://host:port/devtools/browser` endpoint instead, `Target.getTargets`
///   to find a page, then `Target.attachToTarget{flatten:true}` to obtain a
///   `sessionId` that has to ride along on every subsequent message. This is
///   the path for a CDP port that doesn't serve `/json` at all — observed
///   with newer Chrome's in-browser "allow remote debugging" toggle for an
///   already-running profile, which opens the browser endpoint without the
///   classic HTTP discovery endpoints. Re-attaching to a *different* target
///   on this same connection (via `ensure_target`) is what lets
///   `CdpSessionCache` switch tabs without opening a new socket.
struct CdpSession {
    connection: Arc<CdpConnection>,
    session_id: Option<String>,
    /// URL of whichever target we're currently attached to/connected to —
    /// used by `ensure_target` to decide whether a re-attach is needed.
    current_target_url: Option<String>,
}

impl CdpSession {
    async fn connect(port: u16, target_url_contains: Option<&str>) -> anyhow::Result<Self> {
        match ws_url_for_page_target(port, target_url_contains).await {
            Ok((ws_url, target_url)) => {
                let connection = Arc::new(
                    CdpConnection::connect(&ws_url)
                        .await
                        .map_err(|e| anyhow::anyhow!("WebSocket connect failed: {e}"))?,
                );
                Ok(Self {
                    connection,
                    session_id: None,
                    current_target_url: Some(target_url),
                })
            }
            Err(page_discovery_err) => {
                Self::connect_via_browser_endpoint(port, target_url_contains, page_discovery_err)
                    .await
            }
        }
    }

    async fn connect_via_browser_endpoint(
        port: u16,
        target_url_contains: Option<&str>,
        page_discovery_err: anyhow::Error,
    ) -> anyhow::Result<Self> {
        let browser_ws_url = format!("ws://127.0.0.1:{port}/devtools/browser");
        let connection = Arc::new(CdpConnection::connect(&browser_ws_url).await.map_err(|e| {
            anyhow::anyhow!(
                "No /json page discovery on port {port} ({page_discovery_err}), and \
                 connecting to the browser-level endpoint also failed: {e}"
            )
        })?);
        let mut session = Self {
            connection,
            session_id: None,
            current_target_url: None,
        };
        session.attach_to_target(port, target_url_contains).await?;
        Ok(session)
    }

    /// Make sure we're attached to the tab `target_url_contains` selects
    /// (or, with no hint, whatever we're already attached to — anything is
    /// fine). Re-attaching on an already-open browser-endpoint connection
    /// via `Target.getTargets`/`Target.attachToTarget` does NOT reopen the
    /// socket, so it doesn't re-trigger Chrome's confirmation popup —
    /// that's the whole reason this exists instead of always reconnecting.
    async fn ensure_target(
        &mut self,
        port: u16,
        target_url_contains: Option<&str>,
    ) -> anyhow::Result<()> {
        if self.session_id.is_some() {
            // Flattened browser-endpoint mode: always re-resolve + reattach
            // on the SAME connection (Target.getTargets/attachToTarget,
            // never a new socket, so it's cheap and doesn't reprompt).
            //
            // Deliberately does NOT skip this when `current_target_url`
            // already matches the hint — a brand-new tab can carry the
            // exact same URL as a tab that was just closed (e.g. reopening
            // the same compose page), and the cache has no way to tell
            // "same URL" apart from "same still-alive target" without
            // asking Chrome. Confirmed live: skipping this on a URL-only
            // match kept sending Input.insertText into a closed target's
            // dead session — no error, text just never appeared anywhere.
            self.attach_to_target(port, target_url_contains).await
        } else {
            // Classic mode is tied to one page's own websocket URL — there's
            // no in-place retarget, but this mode never shows the popup
            // (it's the dedicated-automation-profile route), so a full
            // reconnect here is cheap and harmless.
            *self = Self::connect(port, target_url_contains).await?;
            Ok(())
        }
    }

    async fn attach_to_target(
        &mut self,
        port: u16,
        target_url_contains: Option<&str>,
    ) -> anyhow::Result<()> {
        let targets = self
            .call("Target.getTargets", serde_json::json!({}))
            .await?;
        let infos = targets["targetInfos"]
            .as_array()
            .cloned()
            .unwrap_or_default();
        let pages: Vec<&serde_json::Value> = infos
            .iter()
            .filter(|t| t.get("type").and_then(|v| v.as_str()) == Some("page"))
            .collect();
        let target = pick_target(&pages, target_url_contains).ok_or_else(|| {
            anyhow::anyhow!("Target.getTargets returned no page target on port {port}")
        })?;
        let target_id = target
            .get("targetId")
            .and_then(|v| v.as_str())
            .ok_or_else(|| anyhow::anyhow!("Target.getTargets entry missing targetId"))?
            .to_owned();
        let target_url = target
            .get("url")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_owned();

        let attach = self
            .call(
                "Target.attachToTarget",
                serde_json::json!({ "targetId": target_id, "flatten": true }),
            )
            .await?;
        let session_id = attach["sessionId"]
            .as_str()
            .ok_or_else(|| anyhow::anyhow!("Target.attachToTarget did not return a sessionId"))?
            .to_owned();
        self.session_id = Some(session_id);
        self.current_target_url = Some(target_url);
        Ok(())
    }

    /// Send one command through the shared event-aware CDP demultiplexer.
    async fn call(
        &mut self,
        method: &str,
        params: serde_json::Value,
    ) -> anyhow::Result<serde_json::Value> {
        self.connection
            .call(self.session_id.as_deref(), method, params)
            .await
    }
}

/// Resolve the websocket debugger URL (and the target's own URL) for the
/// page target `target_url_contains` selects, via the classic `/json` HTTP
/// discovery. Errors (not just returns None) so `CdpSession::connect` can
/// report exactly why the classic path failed if the browser-endpoint
/// fallback also fails.
async fn ws_url_for_page_target(
    port: u16,
    target_url_contains: Option<&str>,
) -> anyhow::Result<(String, String)> {
    let json = http_get_json(port).await?;
    let targets: serde_json::Value =
        serde_json::from_str(&json).map_err(|e| anyhow::anyhow!("CDP /json parse error: {e}"))?;

    let pages: Vec<&serde_json::Value> = targets
        .as_array()
        .map(|arr| {
            arr.iter()
                .filter(|t| t.get("type").and_then(|v| v.as_str()) == Some("page"))
                .collect()
        })
        .unwrap_or_default();

    let target = pick_target(&pages, target_url_contains)
        .ok_or_else(|| anyhow::anyhow!("No page target found on port {port}"))?;
    let ws_url = target
        .get("webSocketDebuggerUrl")
        .and_then(|v| v.as_str())
        .ok_or_else(|| {
            anyhow::anyhow!("No page target with webSocketDebuggerUrl found on port {port}")
        })?
        .to_owned();
    let target_url = target
        .get("url")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .to_owned();
    Ok((ws_url, target_url))
}

/// Pick the unique page target whose `url` contains `hint`
/// (case-insensitive), or the first page when no hint is given. Explicit
/// hints fail closed when zero or multiple pages match. Shared by both
/// discovery paths (classic `/json` and
/// `Target.getTargets`) since a browser with more than one tab open is
/// otherwise picked non-deterministically — CDP target ids carry no
/// relationship to the caller's `window_id`.
fn pick_target<'a>(
    pages: &[&'a serde_json::Value],
    hint: Option<&str>,
) -> Option<&'a serde_json::Value> {
    match hint {
        None => pages.first().copied(),
        Some(hint) => {
            let hint_lower = hint.to_ascii_lowercase();
            let mut matches = pages.iter().copied().filter(|target| {
                target
                    .get("url")
                    .and_then(|value| value.as_str())
                    .is_some_and(|url| url.to_ascii_lowercase().contains(&hint_lower))
            });
            let target = matches.next()?;
            if matches.next().is_some() {
                return None;
            }
            Some(target)
        }
    }
}

#[cfg(test)]
mod tests {
