    fn pages() -> Vec<serde_json::Value> {
        vec![
            serde_json::json!({ "type": "page", "url": "app://fixture/#window-a" }),
            serde_json::json!({ "type": "page", "url": "app://fixture/#window-b" }),
        ]
    }

