#[test]
#[ignore]
fn agent_cursor_overlay_obeys_untargeted_and_targeted_z_order() {
    let case = CaseSpec::delivered(
        "windows-desktop-agent-cursor-px",
        "desktop",
        "win32",
        "agent_cursor",
        Targeting::Px,
        Delivery::NotApplicable,
        Scope::Desktop,
        DriverRoute::WindowsOverlay,
        vec![
            OracleKind::Pixels,
            OracleKind::Focus,
            OracleKind::ZOrder,
            OracleKind::Cursor,
        ],
    );
    execute_case(case, |evidence| {
        let mut driver = McpDriver::spawn_named_with_overlay("windows-desktop-agent-cursor-px")
            .expect("required source-built driver with cursor overlay did not start");
        *evidence = recording_evidence(driver.recording_dir());
        let target = launch_wpf_window(&mut driver);
        bring_to_front(&mut driver, target);
        driver.start_behavior_recording();
        let (x, y) = window_center(target.native_id);
        let cursor_id = "windows-agent-cursor-e2e";
        let foreground_before = unsafe { GetForegroundWindow() };
        assert_eq!(foreground_before.0 as u64, target.native_id);
        let real_cursor_before = real_cursor_position();

        for (tool, arguments) in [
            (
                "set_agent_cursor_enabled",
                serde_json::json!({"enabled": true, "cursor_id": cursor_id}),
            ),
            (
                "set_agent_cursor_motion",
                serde_json::json!({
                    "cursor_id": cursor_id,
                    "glide_duration_ms": 100,
                    "idle_hide_ms": 0
                }),
            ),
            (
                "move_cursor",
                serde_json::json!({
                    "x": x,
                    "y": y,
                    "cursor_id": cursor_id
                }),
            ),
        ] {
            let response = driver.call(tool, arguments);
            assert!(!response.is_error(), "{tool} failed: {}", response.text());
        }
        std::thread::sleep(Duration::from_millis(350));

        let overlay = wait_for_overlay();
        assert_eq!(
            unsafe { GetForegroundWindow() },
            foreground_before,
            "move-only cursor stole focus"
        );
        assert_eq!(
            real_cursor_position(),
            real_cursor_before,
            "move-only agent cursor moved the real pointer"
        );
        assert_not_topmost(overlay);
        assert!(
            window_is_above(overlay, HWND(target.native_id as *mut _)),
            "move-only overlay did not reach the top of the ordinary band"
        );

        let png = platform_windows::capture::screenshot_display_bytes()
            .expect("screenshot_display_bytes failed");
        let image = image::load_from_memory(&png)
            .expect("decode display screenshot")
            .to_rgba8();
        let (image_width, image_height) = image.dimensions();
        let half = 20u32;
        let center_x = x
            .round()
            .clamp(0.0, f64::from(image_width.saturating_sub(1))) as u32;
        let center_y = y
            .round()
            .clamp(0.0, f64::from(image_height.saturating_sub(1))) as u32;
        let x0 = center_x.saturating_sub(half);
        let x1 = center_x.saturating_add(half).min(image_width);
        let y0 = center_y.saturating_sub(half);
        let y1 = center_y.saturating_add(half).min(image_height);
        let visible_pixels = (y0..y1)
            .flat_map(|pixel_y| (x0..x1).map(move |pixel_x| (pixel_x, pixel_y)))
            .filter(|(pixel_x, pixel_y)| {
                let [red, green, blue, alpha] = image.get_pixel(*pixel_x, *pixel_y).0;
                if alpha < 10 {
                    return false;
                }
                let brightness = u32::from(red) + u32::from(green) + u32::from(blue);
                let saturation = u32::from(red.max(green).max(blue) - red.min(green).min(blue));
                brightness > 60 && (saturation > 30 || brightness > 600)
            })
            .count();
        assert!(
            visible_pixels >= 5,
            "agent cursor not visible at ({x:.0},{y:.0}): only {visible_pixels} qualifying pixels"
        );

        // Capture the target while it is still foreground. Electron may prune
        // parts of its UIA tree once another full-size window covers it, but
        // the snapshot remains a stable handle for the later background click.
        let target_state = wait_for_window_text(&mut driver, target, "btn-increment");
        let button_index = ax::element_index_by_id(target_state.tree_text(), "btn-increment")
            .unwrap_or_else(|| {
                panic!(
                    "target increment button missing from foreground UIA snapshot: {}",
                    target_state.tree_text()
                )
            });
        assert!(target_state.tree_text().contains("counter=0"));

        // A targeted cursor remains exactly above its target while an
        // independent ordinary foreground window stays above both. This
        // guards the pre-existing PinAbove semantics while exercising the new
        // no-target branch in the same hosted desktop.
        let (_foreground_profile, foreground) = launch_normal_window(&mut driver, "foreground");
        bring_to_front(&mut driver, foreground);
        assert!(
            window_is_above(
                HWND(foreground.native_id as *mut _),
                HWND(target.native_id as *mut _)
            ),
            "independent foreground window did not cover target"
        );
        let targeted = driver.call(
            "click",
            serde_json::json!({
                "pid": target.pid,
                "window_id": target.native_id,
                "element_index": button_index,
                "snapshot_id": target_state.snapshot_id(),
                "delivery_mode": "background",
                "cursor_id": cursor_id
            }),
        );
        assert!(
            !targeted.is_error(),
            "targeted background click failed: {}",
            targeted.text()
        );
        let target_state_after = wait_for_window_text(&mut driver, target, "counter=1");
        assert!(
            target_state_after.tree_text().contains("counter=1"),
            "targeted click did not change the background target: {}",
            target_state_after.tree_text()
        );
        let foreground_state_after = window_state(&mut driver, foreground);
        assert!(
            foreground_state_after.tree_text().contains("counter=0"),
            "targeted click leaked into the independent foreground window: {}",
            foreground_state_after.tree_text()
        );
        wait_until(
            Duration::from_secs(2),
            "target-bound overlay z-order",
            || {
                window_is_above(overlay, HWND(target.native_id as *mut _))
                    && window_is_above(HWND(foreground.native_id as *mut _), overlay)
            },
        );
        assert_eq!(
            unsafe { GetForegroundWindow().0 as u64 },
            foreground.native_id,
            "target-bound overlay or action stole foreground"
        );
        assert_not_topmost(overlay);

        let disabled = driver.call(
            "set_agent_cursor_enabled",
            serde_json::json!({"enabled": false, "cursor_id": cursor_id}),
        );
        assert!(
            !disabled.is_error(),
            "failed to disable agent cursor: {}",
            disabled.text()
        );
        let passed = vec![
            OracleKind::Pixels,
            OracleKind::Focus,
            OracleKind::ZOrder,
            OracleKind::Cursor,
        ];
        Observation::delivered(passed, Evidence::default())
    });
}

#[test]
#[ignore]
fn agent_cursor_move_does_not_leak_input() {
    let case = CaseSpec::delivered(
        "windows-desktop-agent-cursor-no-input-leak",
        "desktop",
        "win32",
        "agent_cursor",
        Targeting::Px,
        Delivery::NotApplicable,
        Scope::Desktop,
        DriverRoute::WindowsOverlay,
        vec![
            OracleKind::Focus,
            OracleKind::ZOrder,
            OracleKind::Cursor,
            OracleKind::NoLeakedInput,
        ],
    );
    execute_case(case, |evidence| {
        let mut driver =
            McpDriver::spawn_named_with_overlay("windows-desktop-agent-cursor-no-input-leak")
                .expect("required source-built driver with cursor overlay did not start");
        *evidence = recording_evidence(driver.recording_dir());
        let sentinel = ForegroundSentinel::launch(&mut driver);
        driver.start_behavior_recording();
        let screen = driver.call("get_screen_size", serde_json::json!({}));
        assert!(
            !screen.is_error(),
            "get_screen_size failed: {}",
            screen.text()
        );
        let x = screen.structured()["width"].as_f64().unwrap_or(0.0) / 2.0;
        let y = screen.structured()["height"].as_f64().unwrap_or(0.0) / 2.0;
        let cursor_id = "windows-agent-cursor-no-input-leak";
        let (_, passed) = sentinel
            .observe_desktop(|| {
                for (tool, arguments) in [
                    (
                        "set_agent_cursor_enabled",
                        serde_json::json!({"enabled": true, "cursor_id": cursor_id}),
                    ),
                    (
                        "set_agent_cursor_motion",
                        serde_json::json!({
                            "cursor_id": cursor_id,
                            "glide_duration_ms": 100,
                            "idle_hide_ms": 0
                        }),
                    ),
                    (
                        "move_cursor",
                        serde_json::json!({
                            "x": x,
                            "y": y,
                            "cursor_id": cursor_id
                        }),
                    ),
                ] {
                    let response = driver.call(tool, arguments);
                    assert!(!response.is_error(), "{tool} failed: {}", response.text());
                }
                std::thread::sleep(Duration::from_millis(350));
            })
            .unwrap_or_else(|error| panic!("agent cursor disturbed the real desktop: {error}"));
        assert_required_background_oracles(&passed);
        Observation::delivered(passed, Evidence::default())
    });
}

fn window_state(driver: &mut McpDriver, target: TargetWindow) -> cua_driver_testkit::ToolResponse {
    let response = driver.call(
        "get_window_state",
        serde_json::json!({
            "pid": target.pid,
            "window_id": target.native_id,
            "capture_mode": "ax"
        }),
    );
    assert!(
        !response.is_error(),
        "window snapshot failed: {}",
        response.text()
    );
    response
}

fn wait_for_window_text(
    driver: &mut McpDriver,
    target: TargetWindow,
    expected: &str,
) -> cua_driver_testkit::ToolResponse {
    let deadline = Instant::now() + Duration::from_secs(2);
    loop {
        let state = window_state(driver, target);
        if state.tree_text().contains(expected) {
            return state;
        }
        assert!(
            Instant::now() < deadline,
            "window state did not contain {expected:?}: {}",
            state.tree_text()
        );
        std::thread::sleep(Duration::from_millis(50));
    }
}

fn assert_required_background_oracles(passed: &[OracleKind]) {
    for required in [
        OracleKind::Focus,
        OracleKind::ZOrder,
        OracleKind::Cursor,
        OracleKind::NoLeakedInput,
    ] {
        assert!(
            passed.contains(&required),
            "agent cursor test omitted required {required:?} oracle"
        );
    }
}

fn launch_normal_window(driver: &mut McpDriver, label: &str) -> (tempfile::TempDir, TargetWindow) {
    let executable = harness_app("harness-electron", "CuaTestHarness.Electron.exe");
    assert!(
        executable.exists(),
        "Electron harness missing at {}; run the Windows harness build first",
        executable.display()
    );
    let profile = tempfile::Builder::new()
        .prefix(&format!("cua-agent-cursor-{label}-"))
        .tempdir()
        .expect("create Electron profile");
    let port = TcpListener::bind(("127.0.0.1", 0))
        .and_then(|listener| listener.local_addr())
        .expect("allocate Electron CDP port")
        .port();
    let mut command = Command::new(executable);
    command
        .env("CUA_ELECTRON_CDP_PORT", port.to_string())
        .env("CUA_E2E_USER_DATA_DIR", profile.path())
        .stdout(Stdio::null())
        .stderr(Stdio::null());
    let child = spawn_in_job(&mut command).expect("launch ordinary Electron harness window");
    let pid = child.id();
    driver.reaper().push(child);
    let (native_id, _) = driver
        .find_window(pid as i64, "CuaTestHarness Electron")
        .expect("ordinary Electron harness window did not appear");
    (profile, TargetWindow { pid, native_id })
}

fn launch_wpf_window(driver: &mut McpDriver) -> TargetWindow {
    let executable = harness_app("harness-wpf", "CuaTestHarness.Wpf.exe");
    assert!(
        executable.exists(),
        "WPF harness missing at {}; run the Windows harness build first",
        executable.display()
    );
    let mut command = Command::new(executable);
    command.stdout(Stdio::null()).stderr(Stdio::null());
    let child = spawn_in_job(&mut command).expect("launch ordinary WPF harness window");
    let pid = child.id();
    driver.reaper().push(child);
    let (native_id, _) = driver
        .find_window(pid as i64, "CuaTestHarness WPF")
        .expect("ordinary WPF harness window did not appear");
    TargetWindow { pid, native_id }
}

fn bring_to_front(driver: &mut McpDriver, target: TargetWindow) {
    let response = driver.call(
        "bring_to_front",
        serde_json::json!({"pid": target.pid, "window_id": target.native_id}),
    );
    assert!(
        !response.is_error(),
        "bring_to_front failed: {}",
        response.text()
    );
    wait_until(
        Duration::from_secs(2),
        "ordinary window foreground",
        || unsafe { GetForegroundWindow().0 as u64 == target.native_id },
    );
}

fn wait_for_overlay() -> HWND {
    let class_name: Vec<u16> = OsStr::new("Cua.AgentCursorOverlay\0")
        .encode_wide()
        .collect();
    let mut overlay = HWND::default();
    wait_until(
        Duration::from_secs(2),
        "agent cursor overlay window",
        || {
            overlay = unsafe { FindWindowW(PCWSTR(class_name.as_ptr()), PCWSTR::null()) }
                .unwrap_or_default();
            !overlay.0.is_null()
        },
    );
    overlay
}

fn window_center(window_id: u64) -> (f64, f64) {
    let mut rect = RECT::default();
    unsafe { GetWindowRect(HWND(window_id as *mut _), &mut rect) }
        .expect("read ordinary foreground window bounds");
    (
        f64::from(rect.left + (rect.right - rect.left) / 2),
        f64::from(rect.top + (rect.bottom - rect.top) / 2),
    )
}

fn real_cursor_position() -> (i32, i32) {
    let mut point = POINT::default();
    unsafe { GetCursorPos(&mut point) }.expect("read real cursor position");
    (point.x, point.y)
}

fn assert_not_topmost(window: HWND) {
    let ex_style = unsafe { GetWindowLongPtrW(window, GWL_EXSTYLE) } as u32;
    assert_eq!(
        ex_style & WS_EX_TOPMOST.0,
        0,
        "agent cursor overlay remained persistently topmost"
    );
}

fn window_is_above(upper: HWND, lower: HWND) -> bool {
    let mut cursor = lower;
    loop {
        cursor = unsafe { GetWindow(cursor, GW_HWNDPREV) }.unwrap_or_default();
        if cursor.0.is_null() {
            return false;
        }
        if cursor == upper {
            return true;
        }
    }
}

fn wait_until(timeout: Duration, description: &str, mut predicate: impl FnMut() -> bool) {
    let deadline = Instant::now() + timeout;
    while !predicate() {
        assert!(
            Instant::now() < deadline,
            "timed out after {timeout:?} waiting for {description}"
        );
        std::thread::sleep(Duration::from_millis(25));
    }
}

//! One embedded daemon, two public client models.
//!
//! The SDK route uses the generated UniFFI implementation crate directly; the
//! agent route uses the ordinary stdio MCP proxy returned by the same host.

use std::collections::BTreeSet;
use std::io::{BufRead, BufReader, Write};
use std::process::{Command, Stdio};
use std::time::{Duration, Instant};

use cua_driver_contract::{CaptureScope, GetSessionStateInput, StartSessionInput};
use cua_driver_sdk::{CuaDriver, DriverError, EmbeddedCuaDriverHost, EmbeddedDriverHostState};
use cua_driver_testkit::{spawn_in_job, ChildReaper};
use serde_json::{json, Value};

fn read_json(reader: &mut BufReader<std::process::ChildStdout>) -> Value {
    let mut line = String::new();
    reader.read_line(&mut line).expect("read MCP response");
    serde_json::from_str(line.trim()).expect("parse MCP response")
}

fn tool_names(value: &Value, field: &str) -> BTreeSet<String> {
    value[field]
        .as_array()
        .expect("tools array")
        .iter()
        .map(|tool| tool["name"].as_str().expect("tool name").to_owned())
        .collect()
}

#[cfg(unix)]
fn process_is_alive(pid: u32) -> bool {
    // Signal zero performs existence/permission validation without delivering
    // a signal. The child has the same uid, so EPERM cannot mask a live child.
    unsafe { libc::kill(pid as i32, 0) == 0 }
}

#[cfg(not(unix))]
fn process_is_alive(_pid: u32) -> bool {
    // Named-pipe disappearance remains the portable assertion. Windows CI
    // additionally runs the host in a kill-on-close Job Object.
    false
}

#[cfg(unix)]
fn write_test_shell_script(path: &std::path::Path, body: &str) {
    use std::os::unix::fs::PermissionsExt as _;

    // Nix build sandboxes intentionally do not provide `/bin/sh`. Resolve the
    // shell supplied by the test environment so these lifecycle fixtures test
    // the host behavior instead of the host filesystem layout.
    let shell = std::env::var_os("SHELL")
        .map(std::path::PathBuf::from)
        .filter(|candidate| candidate.is_file())
        .or_else(|| {
            std::env::var_os("PATH").and_then(|path| {
                std::env::split_paths(&path)
                    .map(|directory| directory.join("sh"))
                    .find(|candidate| candidate.is_file())
            })
        })
        .expect("test environment must provide a shell");
    let script = format!("#!{}\n{body}\n", shell.display());
    let status = std::process::Command::new(&shell)
        .args([
            std::ffi::OsStr::new("-c"),
            std::ffi::OsStr::new("umask 077; printf '%s' \"$1\" > \"$2\""),
            std::ffi::OsStr::new("cua-driver-test-fixture-writer"),
        ])
        .arg(script)
        .arg(path)
        .status()
        .expect("spawn test fixture writer");
    assert!(status.success(), "test fixture writer failed: {status}");
    std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o700)).unwrap();
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn embedded_host_serves_sdk_and_mcp_with_one_contract() {
    let host = EmbeddedCuaDriverHost::new(
        env!("CARGO_BIN_EXE_cua-driver").into(),
        "com.trycua.embedded-contract-test".into(),
    )
    .expect("construct host");
    let connection = host.clone().start().await.expect("start embedded host");
    assert_eq!(host.state(), EmbeddedDriverHostState::Ready);

    let sdk = CuaDriver::connect(Some(connection.socket_path.clone())).expect("connect SDK");
    let metadata = sdk.metadata().await.expect("SDK metadata handshake");
    assert!(metadata.embedded);
    assert_eq!(metadata.pid, connection.pid);
    assert_eq!(metadata.contract_version, connection.contract_version);
    assert_eq!(
        metadata.host_bundle_id.as_deref(),
        Some("com.trycua.embedded-contract-test")
    );
    let sdk_tools: Value =
        serde_json::from_str(&sdk.list_tools_json().await.expect("SDK tools/list")).unwrap();

    let mut proxy_command = Command::new(&connection.mcp.command);
    proxy_command
        .args(&connection.mcp.args)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::null());
    for variable in &connection.mcp.environment {
        proxy_command.env(&variable.name, &variable.value);
    }
    let mut proxy = spawn_in_job(&mut proxy_command).expect("spawn MCP proxy");
    let mut stdin = proxy.stdin.take().unwrap();
    let mut stdout = BufReader::new(proxy.stdout.take().unwrap());

    writeln!(
        stdin,
        "{}",
        json!({
            "jsonrpc": "2.0",
            "id": 1,
            "method": "initialize",
            "params": {
                "protocolVersion": connection.mcp_protocol_version,
                "capabilities": {},
                "clientInfo": {"name": "embedded-contract-test", "version": "1"}
            }
        })
    )
    .unwrap();
    stdin.flush().unwrap();
    let initialize = read_json(&mut stdout);
    assert_eq!(initialize["id"], 1);
    assert!(initialize.get("result").is_some(), "{initialize:?}");

    writeln!(
        stdin,
        "{}",
        json!({"jsonrpc":"2.0","method":"notifications/initialized","params":{}})
    )
    .unwrap();
    writeln!(
        stdin,
        "{}",
        json!({"jsonrpc":"2.0","id":2,"method":"tools/list","params":{}})
    )
    .unwrap();
    stdin.flush().unwrap();
    let listed = read_json(&mut stdout);
    let mcp_tools = tool_names(&listed["result"], "tools");
    assert_eq!(mcp_tools, tool_names(&sdk_tools, "tools"));
    assert!(mcp_tools.contains("get_desktop_state"));
    assert!(mcp_tools.contains("start_session"));

    let sdk_session = sdk
        .start_session(StartSessionInput {
            session: Some("embedded-sdk-window".into()),
            capture_scope: Some(CaptureScope::Window),
            cursor_theme: None,
        })
        .await
        .expect("start SDK-owned session");
    assert_eq!(sdk_session.state.capture_scope, CaptureScope::Window);

    writeln!(
        stdin,
        "{}",
        json!({
            "jsonrpc": "2.0",
            "id": 3,
            "method": "tools/call",
            "params": {
                "name": "start_session",
                "arguments": {
                    "session": "embedded-mcp-desktop",
                    "capture_scope": "desktop"
                }
            }
        })
    )
    .unwrap();
    stdin.flush().unwrap();
    let mcp_started = read_json(&mut stdout);
    assert_eq!(
        mcp_started["result"]["structuredContent"]["capture_scope"],
        "desktop"
    );

    // Session policy belongs to the session and ordinary lifecycle inspection
    // is transport-scoped: the SDK and MCP connections can each inspect their
    // own session without enumerating the other's label.
    let sdk_state = sdk
        .get_session_state(GetSessionStateInput {
            session: Some("embedded-sdk-window".into()),
        })
        .await
        .expect("read SDK session");
    let foreign = sdk
        .get_session_state(GetSessionStateInput {
            session: Some("embedded-mcp-desktop".into()),
        })
        .await
        .expect_err("SDK transport must not inspect an MCP-created session");
    assert_eq!(sdk_state.capture_scope, CaptureScope::Window);
    assert!(matches!(
        foreign,
        DriverError::Tool { error_code, .. } if error_code == "session_not_started"
    ));

    writeln!(
        stdin,
        "{}",
        json!({
            "jsonrpc": "2.0",
            "id": 4,
            "method": "tools/call",
            "params": {
                "name": "get_session",
                "arguments": {"session": "embedded-mcp-desktop"}
            }
        })
    )
    .unwrap();
    stdin.flush().unwrap();
    let mcp_state = read_json(&mut stdout);
    assert_eq!(
        mcp_state["result"]["structuredContent"]["session"],
        "embedded-mcp-desktop"
    );

    drop(stdin);
    let mut reaper = ChildReaper::new();
    reaper.push(proxy);
    host.clone().stop().await.expect("stop embedded host");
    assert_eq!(host.state(), EmbeddedDriverHostState::Stopped);
    assert!(!std::path::Path::new(&connection.socket_path).exists());
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn dropping_the_host_cannot_orphan_its_daemon() {
    let host = EmbeddedCuaDriverHost::new(
        env!("CARGO_BIN_EXE_cua-driver").into(),
        "com.trycua.embedded-drop-test".into(),
    )
    .expect("construct host");
    let connection = host.clone().start().await.expect("start embedded host");
    drop(host);

    let deadline = Instant::now() + Duration::from_secs(3);
    while Instant::now() < deadline {
        if !CuaDriver::connect(Some(connection.socket_path.clone()))
            .unwrap()
            .is_available()
            && !process_is_alive(connection.pid)
        {
            return;
        }
        tokio::time::sleep(Duration::from_millis(25)).await;
    }
    panic!(
        "embedded daemon survived host drop: pid={}, endpoint={}",
        connection.pid, connection.socket_path
    );
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn concurrent_start_coalesces_and_restart_rotates_generation() {
    let host = EmbeddedCuaDriverHost::new(
        env!("CARGO_BIN_EXE_cua-driver").into(),
        "com.trycua.embedded-lifecycle-test".into(),
    )
    .expect("construct host");

    let (left, right, third) = tokio::join!(
        host.clone().start(),
        host.clone().start(),
        host.clone().start()
    );
    let left = left.expect("first start");
    let right = right.expect("second start");
    let third = third.expect("third start");
    assert_eq!(left, right);
    assert_eq!(left, third);

    let first_generation = left.generation.clone();
    let restarted = host.clone().restart().await.expect("restart host");
    assert_ne!(restarted.generation, first_generation);
    assert_eq!(host.connection().as_ref(), Some(&restarted));

    host.clone().stop().await.expect("stop host");
    let exit = host
        .clone()
        .wait_for_exit(restarted.generation.clone())
        .await
        .expect("observe stopped generation");
    assert_eq!(exit.generation, restarted.generation);
    assert!(
        exit.success,
        "graceful lifetime-pipe shutdown should succeed"
    );
}

#[cfg(unix)]
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn stop_cancels_startup_and_unblocks_every_waiter() {
    let directory = tempfile::tempdir().unwrap();
    let binary = directory.path().join("never-ready-driver");
    write_test_shell_script(&binary, "read _");
    let host = EmbeddedCuaDriverHost::new(
        binary.to_string_lossy().into_owned(),
        "com.trycua.embedded-cancel-test".into(),
    )
    .expect("construct host");

    let starting = tokio::spawn(host.clone().start());
    let deadline = Instant::now() + Duration::from_secs(2);
    while host.state() != EmbeddedDriverHostState::Starting && Instant::now() < deadline {
        tokio::time::sleep(Duration::from_millis(10)).await;
    }
    assert_eq!(host.state(), EmbeddedDriverHostState::Starting);

    host.clone().stop().await.expect("cancel startup");
    let start_error = starting.await.unwrap().unwrap_err();
    assert!(matches!(
        start_error,
        cua_driver_sdk::EmbeddedDriverError::StartupCancelled
    ));
    assert_eq!(host.state(), EmbeddedDriverHostState::Stopped);
}

#[cfg(unix)]
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn early_child_exit_resets_the_host_to_stopped() {
    let directory = tempfile::tempdir().unwrap();
    let binary = directory.path().join("early-exit-driver");
    write_test_shell_script(&binary, "exit 7");
    let host = EmbeddedCuaDriverHost::new(
        binary.to_string_lossy().into_owned(),
        "com.trycua.embedded-early-exit-test".into(),
    )
    .expect("construct host");
    for attempt in 1..=64 {
        let error = host.clone().start().await.unwrap_err();
        assert!(
            matches!(
                &error,
                cua_driver_sdk::EmbeddedDriverError::ExitedBeforeReady { code: Some(7) }
            ),
            "attempt {attempt}/64 returned {error:?}"
        );
        assert_eq!(
            host.state(),
            EmbeddedDriverHostState::Stopped,
            "attempt {attempt}/64 did not reset the host after {error:?}"
        );
    }
}

use std::process::Command;

use cua_driver_sdk::{
    ConfiguredDriverOptions, CuaDriver, RuntimeAuthorizationOptions, SessionPermissionMode,
};

const PROBE_ENV: &str = "CUA_DRIVER_SDK_CONFIGURATION_PROBE";

fn options(allowed_modes: Vec<SessionPermissionMode>) -> ConfiguredDriverOptions {
    ConfiguredDriverOptions {
        claude_code_compatibility: false,
        authorization: RuntimeAuthorizationOptions {
            allowed_modes,
            compatibility_mode: SessionPermissionMode::Standard,
            compatibility_capability_manifest_path: None,
            compatibility_bounded_manifest_path: None,
            unrestricted_acknowledged: true,
            max_session_ttl_seconds: 60,
            max_idle_ttl_seconds: 30,
        },
    }
}

#[test]
fn child_configuration_probe() {
    let Ok(case) = std::env::var(PROBE_ENV) else {
        return;
    };
    let result = match case.as_str() {
        "matching" | "conflicting_mode" => {
            CuaDriver::create_configured(options(vec![SessionPermissionMode::Standard]))
        }
        "managed_disable" => CuaDriver::create_configured(options(vec![
            SessionPermissionMode::Standard,
            SessionPermissionMode::Unrestricted,
        ])),
        other => panic!("unknown probe case {other}"),
    };

    match case.as_str() {
        "matching" => {
            if let Err(error) = result {
                panic!("matching environment was rejected: {error}");
            }
        }
        "conflicting_mode" | "managed_disable" => {
            assert!(result.is_err(), "contradictory environment was accepted")
        }
        _ => unreachable!(),
    }
}

fn run_probe(case: &str, environment: &[(&str, &str)]) {
    let mut command = Command::new(std::env::current_exe().expect("current test executable"));
    command
        .args(["--exact", "child_configuration_probe", "--nocapture"])
        .env(PROBE_ENV, case)
        .env_remove("CUA_DRIVER_PERMISSION_MODE")
        .env_remove("CUA_DRIVER_DANGEROUSLY_BYPASS_APPROVALS")
        .env_remove("CUA_DRIVER_DISABLE_UNRESTRICTED")
        .env_remove("CUA_DRIVER_CAPABILITY_MANIFEST_FILE")
        .env_remove("CUA_DRIVER_CAPABILITY_MANIFEST_APPROVED")
        .env_remove("CUA_DRIVER_SESSION_POLICY_FILE")
        .env_remove("CUA_DRIVER_SESSION_POLICY_APPROVED");
    for (name, value) in environment {
        command.env(name, value);
    }
    let output = command.output().expect("run configuration probe");
    assert!(
        output.status.success(),
        "configuration probe {case} failed:\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr),
    );
}

#[test]
fn explicit_runtime_configuration_rejects_contradictory_environment() {
    run_probe("matching", &[("CUA_DRIVER_PERMISSION_MODE", "standard")]);
    run_probe(
        "conflicting_mode",
        &[
            ("CUA_DRIVER_PERMISSION_MODE", "unrestricted"),
            ("CUA_DRIVER_DANGEROUSLY_BYPASS_APPROVALS", "1"),
        ],
    );
    run_probe(
        "managed_disable",
        &[("CUA_DRIVER_DISABLE_UNRESTRICTED", "1")],
    );
}
